#!/usr/bin/env node

/**
 * Test script to verify session persistence with database-backed storage
 * Run: node scripts/test-sessions.js
 */

const { PrismaClient } = require('@prisma/client');
const crypto = require('crypto');

const prisma = new PrismaClient();

const SESSION_TTL = 1000 * 60 * 60 * 24 * 7; // 7 days

async function createSession(userId, role = 'pilot') {
  const sessionId = crypto.randomBytes(24).toString('hex');
  const expiresAt = new Date(Date.now() + SESSION_TTL);
  
  // updatedAt is auto-generated by Prisma (@updatedAt)
  const session = await prisma.session.create({
    data: {
      id: sessionId,
      userId,
      role,
      expiresAt,
      createdAt: new Date(),
      updatedAt: new Date(),
    },
  });
  
  return sessionId;
}

async function getSession(sessionId) {
  if (!sessionId) return null;

  const session = await prisma.session.findUnique({
    where: { id: sessionId },
    select: { userId: true, role: true, expiresAt: true },
  });

  if (!session) return null;

  if (session.expiresAt < new Date()) {
    await destroySession(sessionId);
    return null;
  }

  return {
    userId: session.userId,
    role: session.role,
  };
}

async function destroySession(sessionId) {
  await prisma.session.delete({
    where: { id: sessionId },
  }).catch(() => {
    // Session might not exist, ignore error
  });
}

async function cleanupExpiredSessions() {
  const result = await prisma.session.deleteMany({
    where: {
      expiresAt: {
        lt: new Date(),
      },
    },
  });
  return result.count;
}

async function testSessions() {
  console.log('🧪 Testing Session Persistence\n');
  console.log('=' .repeat(50));

  try {
    // Test 1: Create a session
    console.log('\n✅ Test 1: Creating session...');
    const testUserId = 'test-user-' + Date.now();
    const sessionId = await createSession(testUserId, 'pilot');
    console.log(`   Session ID: ${sessionId.substring(0, 20)}...`);
    console.log(`   User ID: ${testUserId}`);
    console.log('   ✓ Session created successfully');

    // Test 2: Retrieve the session
    console.log('\n✅ Test 2: Retrieving session...');
    const retrievedSession = await getSession(sessionId);
    if (retrievedSession && retrievedSession.userId === testUserId) {
      console.log(`   User ID: ${retrievedSession.userId}`);
      console.log(`   Role: ${retrievedSession.role}`);
      console.log('   ✓ Session retrieved successfully');
    } else {
      throw new Error('Session retrieval failed');
    }

    // Test 3: Verify session exists in database
    console.log('\n✅ Test 3: Verifying session in database...');
    const dbSession = await prisma.session.findUnique({
      where: { id: sessionId },
    });
    if (dbSession) {
      console.log(`   Session found in database`);
      console.log(`   Expires at: ${dbSession.expiresAt.toISOString()}`);
      console.log('   ✓ Session persisted to database');
    } else {
      throw new Error('Session not found in database');
    }

    // Test 4: Test session expiration check
    console.log('\n✅ Test 4: Testing expiration logic...');
    const futureExpiry = new Date(Date.now() + 1000 * 60 * 60); // 1 hour from now
    const expiredSessionId = crypto.randomBytes(24).toString('hex');
    await prisma.session.create({
      data: {
        id: expiredSessionId,
        userId: 'expired-user',
        role: 'pilot',
        expiresAt: new Date(Date.now() - 1000), // Expired 1 second ago
        createdAt: new Date(),
        updatedAt: new Date(),
      },
    });
    
    const expiredSession = await getSession(expiredSessionId);
    if (expiredSession === null) {
      console.log('   ✓ Expired session correctly returns null');
      // Verify it was deleted
      const deletedCheck = await prisma.session.findUnique({
        where: { id: expiredSessionId },
      });
      if (!deletedCheck) {
        console.log('   ✓ Expired session was automatically deleted');
      }
    } else {
      throw new Error('Expired session should return null');
    }

    // Test 5: Test session cleanup
    console.log('\n✅ Test 5: Testing cleanup function...');
    // Create an expired session
    const cleanupTestId = crypto.randomBytes(24).toString('hex');
    await prisma.session.create({
      data: {
        id: cleanupTestId,
        userId: 'cleanup-test',
        role: 'pilot',
        expiresAt: new Date(Date.now() - 1000),
        createdAt: new Date(),
        updatedAt: new Date(),
      },
    });
    
    const deletedCount = await cleanupExpiredSessions();
    console.log(`   Deleted ${deletedCount} expired session(s)`);
    console.log('   ✓ Cleanup function works');

    // Test 6: Test session deletion
    console.log('\n✅ Test 6: Testing session deletion...');
    await destroySession(sessionId);
    const deletedSession = await getSession(sessionId);
    if (deletedSession === null) {
      console.log('   ✓ Session deleted successfully');
    } else {
      throw new Error('Session should be null after deletion');
    }

    // Test 7: Test multiple sessions for same user
    console.log('\n✅ Test 7: Testing multiple sessions...');
    const multiSessionId1 = await createSession(testUserId, 'pilot');
    const multiSessionId2 = await createSession(testUserId, 'pilot');
    const session1 = await getSession(multiSessionId1);
    const session2 = await getSession(multiSessionId2);
    
    if (session1 && session2 && session1.userId === session2.userId) {
      console.log('   ✓ Multiple sessions can exist for same user');
    } else {
      throw new Error('Multiple sessions test failed');
    }

    // Cleanup test sessions
    await destroySession(multiSessionId1);
    await destroySession(multiSessionId2);

    // Test 8: Count sessions in database
    console.log('\n✅ Test 8: Verifying database connection...');
    const sessionCount = await prisma.session.count();
    console.log(`   Total sessions in database: ${sessionCount}`);
    console.log('   ✓ Database connection working');

    console.log('\n' + '='.repeat(50));
    console.log('🎉 All session tests passed!');
    console.log('✅ Session storage is working correctly');
    console.log('✅ Database-backed sessions are production-ready\n');

  } catch (error) {
    console.error('\n❌ Test failed:', error.message);
    console.error(error);
    process.exit(1);
  } finally {
    await prisma.$disconnect();
  }
}

// Run tests
testSessions().catch(console.error);

